\label{lem: Terminal blow up}
Let $(X\ni x,B)$ be a pair such that $X$ is terminal and $\dim x=\dim X-2$. Let $E_1$ be the exceptional divisor obtained by blowing up $x\in X$. If $\operatorname{mult}_x B\leq 1$, then $${\rm{mld}}(X\ni x, B)=a(E_1,X,B)=2-\operatorname{mult}_x B\geq 1.$$
Moreover, ${\rm{mld}}(X\ni x,B)\geq 1$ if and only if $\operatorname{mult}_x B\leq 1$.

\begin{equation}\label{equ: 2-mult equ 1}
    a(E_1,X,B)=2-\operatorname{mult}_xB\leq 2-\operatorname{mult}_{x_{n-1}}B_{n-1}=a(E_n,X_{n-1},B_{n-1}).
\end{equation}

\begin{equation}\label{equ: 2-mult equ 2}
a(E_n,X_{n-1},B_{n-1})\leq a(E_n,X,B)={\rm{mld}}(X\ni x,B)\leq a(E_1,X,B).
\end{equation}

\label{defn: complement}
Let $n$ be a positive integer, $\epsilon$ a non-negative real number, ${\Gamma}_0\subset (0,1]$ a finite set, and $(X/Z\ni z,B)$ and $(X/Z\ni z,B^+)$ two pairs. We say that $(X/Z\ni z,B^+)$ is an \emph{$(\epsilon,\mathbb{R})$-complement} of $(X/Z\ni z,B)$ if 
\begin{itemize}
    \item $(X/Z\ni z,B^+)$ is $\epsilon$-lc,
    \item $B^+\geq B$, and
    \item $K_X+B^+\sim_{\mathbb{R}}0$ over a neighborhood of $z$.
\end{itemize}
We say that $(X/Z\ni z,B^+)$ is an \emph{$(\epsilon,n)$-complement} of $(X/Z\ni z,B)$ if
\begin{itemize}
\item $(X/Z\ni z,B^+)$ is $\epsilon$-lc,
\item $nB^+\geq \lfloor (n+1)\{B\}\rfloor+n\lfloor B\rfloor$, and
\item $n(K_X+B^+)\sim 0$ over a neighborhood of $z$.
\end{itemize}
A $(0,\mathbb{R})$-complement is also called an \emph{$\mathbb{R}$-complement}, and a $(0,n)$-complement is also called an \emph{$n$-complement}. We say that $(X/Z\ni z,B)$ is $(\epsilon,\mathbb{R})$-complementary (resp. $(\epsilon,n)$-complementary, $\mathbb{R}$-complementary, $n$-complementary) if $(X/Z\ni z,B)$ has an $(\epsilon,\mathbb{R})$-complement (resp. $(\epsilon,n)$-complement, $\mathbb{R}$-complement, $n$-complement). 

 We say that $(X/Z\ni z,B^+)$ is a \emph{monotonic $(\epsilon,n)$-complement} of $(X/Z\ni z,B)$ if $(X/Z\ni z,B^+)$ is an $(\epsilon,n)$-complement of $(X/Z\ni z,B)$ and $B^+\geq B$.

 We say that $(X/Z\ni z,B^+)$ is an \emph{$(n,{\Gamma}_0)$-decomposable $\mathbb{R}$-complement} of $(X/Z\ni z,B)$ if there exist a positive integer $k$, $a_1,\dots,a_k\in{\Gamma}_0$, and  $\mathbb{Q}$-divisors $B_1^+,\dots,B_k^+$ on $X$, such that
\begin{itemize}
\item $\sum_{i=1}^ka_i=1$ and  $\sum_{i=1}^ka_iB_i^+=B^+$,
\item $(X/Z\ni z,B^+)$ is an $\mathbb{R}$-complement of $(X/Z\ni z,B)$, and
\item  $(X/Z\ni z,B_i^+)$ is an $n$-complement of itself for each $i$.
\end{itemize}

\label{thm: ni decomposable complement}
Let $d$ be a positive integer and ${\Gamma}\subset [0,1]$ a DCC set. Then there exists a positive integer $n$ and a finite set ${\Gamma}_0\subset (0,1]$ depending only on $d$ and ${\Gamma}$ and satisfy the following. 

Assume that $(X/Z\ni z,B)$ is a pair of dimension $d$ and $B\in{\Gamma}$, such that $X$ is of Fano type over $Z$ and $(X/Z\ni z,B)$ is $\mathbb{R}$-complementary. Then $(X/Z\ni z,B)$ has an $(n,{\Gamma}_0)$-decomposable $\mathbb{R}$-complement. Moreover, if $\bar{\Gamma}\subset\mathbb{Q}$, then $(X/Z\ni z,B)$ has a monotonic $n$-complement.

