\label{lem: canonical threshold attain mld=1}
Let $(X\ni x, B)$ be a threefold germ such that ${\rm{mld}}(X\ni x, B)\geq 1$. Let $D\ge0$ be an $\mathbb{R}$-Cartier $\mathbb{R}$-divisor on $X$ and $t:=\operatorname{ct}(X\ni x, B;D)$. Then ${\rm{mld}}(X\ni x, B+tD)=1$ if one of the following holds:
\begin{enumerate}
    \item $\operatorname{mult}_S (B+tD)<1$ for any prime divisor $S\subset \operatorname{Supp} D$,
    \item $X$ is $\mathbb{Q}$-factorial terminal near $x$ and $x\in X$ is not smooth, and
    \item $X$ is $\mathbb{Q}$-Gorenstein, $x\in X$ is not smooth, and $D$ is a $\mathbb{Q}$-Cartier prime divisor.
\end{enumerate}

\label{thm: 3-dim terminal number of coefficients local}
Let $(X\ni x,B:=\sum_{i=1}^m b_iB_i)$ be a threefold germ such that ${\rm{mld}}(X\ni x,B)\geq 1$, $X$ is terminal, and each $B_i\geq 0$ is a $\mathbb{Q}$-Cartier Weil divisor. Then we have the following:
\begin{enumerate}
    \item If $X\ni x$ is smooth, then $\sum_{i=1}^m b_i\leq 2$.
    \item If $X\ni x$ is not smooth, then $\sum_{i=1}^m b_i\le 1$. Moreover, if $\sum_{i=1}^m b_i=1$, then ${\rm{mld}}(X\ni x, B)=1$.
\end{enumerate}

\begin{align*}
    1&\leq{\rm{mld}}(X\ni x,B)\leq a(E,X,B)=a(E,X,0)-\operatorname{mult}_EB\\
    &=1+\frac{1}{I}-\sum_{i=1}^mb_i\operatorname{mult}_EB_i\leq 1+\frac{1}{I}-\frac{1}{I}\sum_{i=1}^mb_i,
\end{align*}

\label{def: definition of general cP}
Let $x\in X$ be a terminal threefold singularity. By the classification of threefold terminal singularities (cf. \cite[(6.1) Theorem]{Rei87}, \cite[Theorems 12,23,25]{Mor85}), we have an analytic isomorphism $(x\in X)\cong (y\in Y)/\bm{\mu}$ for some isolated cDV singularity $(y\in Y)\subset(o\in\mathbb C^4)$ and cyclic group action $\bm{\mu}$ on $o\in\mathbb C^4$. Moreover, $y\in Y$ is defined by an equation $(f=0)\subset (o\in\mathbb C^4)$ with analytic local coordinates $x_1,x_2,x_3,x_4$, and there exists $1\leq i\leq 4$ such that $f/x_i$ is a rational function that is invariant under the $\bm\mu$-action. Now we consider the $1$-parameter deformation ${Y_\lambda}$ of $Y$, such that $Y_{\lambda}$ is given by $(f+\lambda x_i=0)$. Then the deformation ${Y_\lambda}$ is compatible with the action $\bm{\mu}$, and we let $X_{\lambda}:=Y_{\lambda}/\bm{\mu}$ for each $\lambda$. For a general $\lambda\in\mathbb C$, the singularities of $X_{\lambda}$ are terminal cyclic quotient singularities $Q_1,\dots,Q_m$ for some positive integer $m$. We have the following.
\begin{enumerate}
    \item $Q_1,\dots,Q_m$ only rely on $x\in X$ and are independent of the choice of $\lambda$, and we define the set of \emph{fictitious singularities} of $x\in X$ to be $I_x:=\{Q_1,\dots,Q_m\}$.
    \item For any $\mathbb{Q}$-Cartier Weil divisor $D$ on $X$, $D$ is deformed to a Weil divisor $D_{\lambda}$ on $X_{\lambda}$. We define $c_x(D):=\sum_{j=1}^mc_{Q_j}(D_{\lambda})$.
\end{enumerate}
For such a general $\lambda$, $X_{\lambda}$ is called a \emph{$Q$-smoothing} of $x\in X$.

\label{def: Reid basket for divisorial contractions}
Let $f: Y\to X$ be a divisorial contraction of a prime divisor $F$ such that $Y$ is a terminal threefold.


For any closed point $y\in F$, consider a $Q$-smoothing of $y\in F\subset Y$ as in Definition-Lemma~\ref{def: definition of general cP}, and let $I_y$ be the corresponding set of fictitious singularities. For each $Q_y\in I_y$, let $Y_{Q_y}$ be the deformed variety on which $Q_y\in Y_{Q_y}$ is a cyclic quotient terminal threefold singularity of type $\frac{1}{r_{Q_y}}(1,-1,b_{Q_y})$, and $F_{Q_y}\subset Y_{Q_y}$ the deformed divisor of $F\subset Y$. Let $f_{Q_y}$ be the smallest non-negative integer such that $F_{Q_y}\sim f_{Q_y}K_{Y_{Q_y}}$ near $Q_y$. Possibly replacing $b_{Q_y}$ with $r_{Q_y}-b_{Q_y}$, we may assume that $v_{Q_y}:=\overline{(f_{Q_y}b_{Q_y})}_{r_{Q_y}}\leq \frac{r_{Q_y}}{2}$. The \emph{Reid basket} for the divisorial contraction $f:Y\to X$ with the exceptional divisor $F$ is defined as $$J:=\{(r_{Q_y},v_{Q_y})\mid y\in F, Q_y\in I_y, v_{Q_y}\neq 0\}.$$

\label{defn: exceptional divisor and weighted blow-up}
Let $f': W\to (\mathbb{C}^d\ni o)/\frac{1}{n}(a_1,\dots,a_d)$ be the weighted blow-up at $o$ with the (admissible) weight $w:=\frac{1}{n}(w_1,\dots,w_d)$ with respect to the coordinates $x_1,\dots,x_d$ (cf. \cite[\S 10]{KM92} and \cite[\S 3.2]{Hay99}). The exceptional locus for $f'$, denoted by $E'$, is isomorphic to the cyclic quotient of the weighted projective space $\mathbf{P}(w_1,\dots,w_d)/\bm \eta$, where the cyclic group action is given by $$\bm \eta: [x_1:\dots:x_d]_w\to [\xi_n^{a_1}x_1:\dots,\xi_n^{a_d}x_d]_w,$$ and $[x_1:\dots:x_d]_w$ denotes the image of $(x_1,\dots,x_d)\in \mathbb{C}^d\setminus \{o\}$ under the natural quotient morphism $ \mathbb{C}^d\setminus\{o\}\to \mathbf{P}(w_1,\dots,w_d)$. We remark that if the admissible weight $w$ satisfies $w_i\equiv b a_i\mod n$ for $1\leq i\leq d$ and some integer $b$ such that $\gcd(b,n)=1$, then $E'\cong \mathbf{P}(w_1,\dots,w_d)$ (cf. \cite[\S 3.2]{Hay99}).


Now we have an induced morphism $f: Y\to X$ by restricting $f'$ to $Y$, which is the strict transform of $X$ under $f'$. We call $f: Y\to X$ the \emph{weighted blow-up with weight $w$ at $x\in X$}, and $E:=E'|_{Y}$ the \emph{exceptional divisor of the weighted blow-up $f: Y\to X$ with the weight $w$ at $x\in X$} (cf. \cite[\S 3.7]{Hay99}). If $E$ is an integral scheme, then we also say $f$ \emph{extracts a prime divisor}.

\label{lem: tie breaking canonical pair}
Let $(X\ni x,B)$ be a germ such that $X$ is terminal and ${\rm{mld}}(X\ni x, B)=1$. Then there exists a pair $(X,B')$ that is klt near $x$, such that
\begin{itemize}
    \item $x$ is the only canonical center of $(X,B')$,
    \item there exists exactly one canonical place $E$ of $(X\ni x,B')$, and
    \item $a(E,X,B)=1$.
\end{itemize}

\begin{align*}
    \mathfrak{J}_{1,\epsilon}&:=\{\operatorname{codim} y-\operatorname{mult}_y D_{\epsilon}\mid y\in W, f(y)\neq x,\operatorname{codim} f(y)\geq 2\},~\text{and}\\
    \mathfrak{J}_{2,\epsilon}&:=\{\operatorname{codim} y-\operatorname{mult}_y D_{\epsilon}\mid y\in W, f(y)=x\}.
\end{align*}

\begin{align*}
    \mathfrak{J}'_{1,\epsilon'}&:=\{\operatorname{codim} y-\operatorname{mult}_y D'_{\epsilon'}\mid y\in W, f(y)\neq x,\operatorname{codim} f(y)\geq 2\},~\text{and}\\
    \mathfrak{J}'_{2,\epsilon',\ge2}&:=\{\operatorname{codim} y-\operatorname{mult}_y D'_{\epsilon'}\mid y\in W, f(y)=x,\operatorname{codim} y\geq 2\}.
\end{align*}

Suppose that the lemma does not hold. Then there exists a sequence of threefold germs $\{(X_i\ni x_i, B_i:=\sum_{j=1}^{p_i} b_{i,j}B_{i,j}'))\}_{i=1}^{\infty}$ and terminal blow-ups $f_i: Y_i\rightarrow X_i$ corresponding to $(X\ni x,B:=\sum_{i} b_iB_i')$ and $f:Y\to X$ as in (1)-(6), such that
\begin{itemize}
\item $f_i$ extracts a prime divisor $E_i$,
\item $K_{Y_i}=f_i^*K_{X_i}+\frac{a_i}{I}E_i$ for some positive real number $a_i$, and
\item the following sequence of non-negative integers$$A_i:=\inf\{a_i'\mid F_i\text{ is over }X_i\ni x_i, a(F_i,X_i,B_i)=\alpha, a(F_i,X_i,0)=1+\frac{a_i'}{I}\}$$
    is strictly increasing, and in particular, $\lim_{i\rightarrow+\infty}A_i=+\infty$.
\end{itemize}
Since $f_i$ is a terminal blow-up, $a(E_i,Y_i,B_i)=\alpha$, hence $a_i\geq A_i$. Thus $\lim_{i\rightarrow+\infty}a_i=+\infty$. Possibly passing to a subsequence, we may assume that $a_i$ is strictly increasing and $a_i>5I$ for each $i$. By \cite[Theorem~1.1]{Kaw01} and Theorem \ref{thm: kaw05 1.2 strenghthened}, analytically locally, we have an embedding $$(X_i\ni x_i)\hookrightarrow (\mathbb{C}^{m_i}\ni o)/\frac{1}{n_i}(\alpha_{1,i},\dots,\alpha_{m,i})$$ for each $i$, where $n_i$ is the index of $X_i\ni x_i$, $n_i\mid I$, $m_i\in \{3,4,5\}$, $\alpha_{1,i},\dots,\alpha_{m,i}\in \mathbb{Z}\cap[1,I]$, and $f_i$ is an admissible weighted blow-up with the weight $w_i\in \frac{1}{n_i}\mathbb{Z}_{>0}^{m_i}$. Moreover, for each $i,j$, we may assume that $B_{i,j}'$ is defined by $(h_{i,j}=0)$ for some semi-invariant analytic power series $h_{i,j}$ near $x_i$. 

By Theorems \ref{thm: 3-dim terminal number of coefficients local} and \ref{thm: acc newton polytope}, possibly passing to a subsequence, we may assume that
\begin{itemize}
    \item there exist positive integers $n,m,\alpha_1,\dots,\alpha_m$ and a non-negative integer $p$, such that $n_i=n$, $m_i=m$, $(\alpha_{1,i},\dots,\alpha_{m,i})=(\alpha_1,\dots,\alpha_m)$, and $p_i=p$ for each $i$, 
    \item $b_{i,j}$ is increasing for any fixed $j$, and
    \item $\mathcal{N}(h_{i,j})\subset \mathcal{N}(h_{i',j})$ for any $i>i'$ and any $j$.
\end{itemize}
By Lemma \ref{lem: weighted blowup log discrepancies},
$$\frac{a_i}{I}=w_i(X_i\ni x_i)=w_i(B_i)+\alpha-1=\sum_{j=1}^{p} b_{i,j}w_i(h_{i,j})+\alpha-1.$$

We will show the following claim:

\begin{claim}\label{claim: auxiliary weights}

Possibly passing to a subsequence, we may assume that $(X_1\ni x_1, B_1)$ and $(X_2\ni x_2, B_2)$ satisfy the following:
\begin{enumerate}
    \item $A_2>a_1$, and 
    \item there exists an admissible weighted blow-up $f'$ of $(X_2\ni x_2)\subset(\mathbb{C}^m\ni o)/\frac{1}{n}(\alpha_1,\dots,\alpha_m)$ with the weight $w'\in\frac{1}{n}\mathbb{Z}_{\ge 1}^m$, such that $w_1(B_2)\leq w'(B_2)$, $w'(X_2\ni x_2)=w_1(X_1\ni x_1)$, and the exceptional divisor $E'$ of $f'$ is an analytic prime divisor. 
