    \item $x\in X$ is a terminal singularity of type $cA/n$ for some $n>N:=\lceil\frac{3}{\gamma_0}\rceil$,
    \item $B:=\sum_{i} b_iB_i$ for some $b_i\in {\Gamma}$, where $B_i\geq 0$ are $\mathbb{Q}$-Cartier Weil divisors, 
    \item ${\rm{mld}}(X\ni x,B)\geq 1$, and
    \item there exists a terminal blow-up (see Definition \ref{defn: terminal blow-up}) $f: Y\to X$ of $(X\ni x,B)$ which extracts a prime divisor $E$ over $X\ni x$, such that $a(E,X,0)=1+\frac{a}{n}$ for some positive integer $a\geq 3$.
\end{itemize}
Then there exists a prime divisor $\bar E$ over $X\ni x$ such that $a(\bar E,X,B)={\rm{mld}}(X\ni x, B)$ and $a(\bar E,X,0)=1+\frac{3}{n}$. Moreover,
