\label{defn: newton polytope zd}
Let $n$ be a positive integer. A \emph{Newton polytope} $\mathcal{N}$ is a subset of $\mathbb{Z}_{\geq 0}^n$ satisfying the following: for any point $\bm{x}\in\mathcal{N}$, 
$$\bm{x}+\mathbb{Z}_{\geq 0}^n:=\{\bm{x}+\bm{v}\mid\bm{v}\in\mathbb{Z}_{\geq 0}^n\}\subset\mathcal{N}.$$

\label{lem: basic properties of equivalence relation}
Let $\tilde{X}$ (resp. $\tilde{X}'$) be a reduced equidimensional analytic space with the analytic structure sheaf $\mathcal{O}_{\tilde{X}}$ (resp. $\mathcal{O}_{\tilde{X}'}$), and $\widetilde{Z}\subset \tilde{X}$ (resp. $\tilde{Z}'\subset \tilde{X}'$) a closed analytic subspace with the ideal sheaf $\mathcal{I}_{\tilde{Z}}$ (resp. $\mathcal{I}_{\tilde{Z}'}$). Then the following statements hold.
\begin{enumerate}
    \item If $\tilde{Z}\subset \tilde{X}$ is formal equivalent to $\tilde{Z}'\subset \tilde{X}'$, then $\tilde{Z}\subset \tilde{X}$ is $v$-equivalent to $\tilde{Z}'\subset \tilde{X}'$ for all $v\in \mathbb{Z}_{>0}$.
    \item If $\tilde{Z}\subset \tilde{X}$ is analytic equivalent to $\tilde{Z}'\subset \tilde{X}'$, then $\tilde{Z}\subset \tilde{X}$ is formal equivalent to $\tilde{Z}'\subset \tilde{X}'$.
    \item If $\tilde{Z}\subset \tilde{X}$ is analytic equivalent to $\tilde{Z}'\subset \tilde{X}'$, then there exists an analytic neighborhood $\tilde{U}$ of $\tilde{Z}$ in $\tilde{X}$ (resp. $\tilde{U}'$ of $\tilde{Z}'$ in $\tilde{X}'$), such that the isomorphism $(\tilde{Z}, (\mathcal{O}_{\tilde{X}})|_{\tilde{Z}})\cong (\tilde{Z}', (\mathcal{O}_{\tilde{X}'})|_{\tilde{Z}'})$ extends to an isomorphism $(\tilde{U}, (\mathcal{O}_{\tilde{X}})|_{\tilde{U}})\cong (\tilde{U}', (\mathcal{O}_{\tilde{X}'})|_{\tilde{U}'})$.
    \item Suppose that $\tilde{Z}$ (resp. $\tilde{Z}'$) is a closed point on $\tilde{X}$ (resp. $\tilde{X}'$) and  $\tilde{X}\setminus \tilde{Z}$ (resp. $\tilde{X}'\setminus \tilde{Z}'$) is smooth. Then there exists a positive integer $c_2$, such that if $\tilde{Z}\subset \tilde{X}$ is $v$-equivalent to $\tilde{Z}'\subset \tilde{X}'$ for some integer $v\geq  c_2$, then $\tilde{Z}\subset \tilde{X}$ is analytic equivalent to $\tilde{Z}'\subset \tilde{X}'$.
\end{enumerate}

