\label{lem: cD irreducible case 1}
Let $f: Y\to X$ be a divisorial contraction of a prime divisor over $X\ni x$ and $r,a,d$ the corresponding positive integers as in Theorem~\ref{thm: kaw05 1.2 strenghthened}(2.1).
\begin{enumerate}
    \item For any weight $w':=(r'+1,r',a',1)\in\mathbb Z_{>0}^4$ such that $2r'+1=a'd$ and $2\leq a'<a$, the weighted blow-up $f':Y'\to X$ with the weight $w'$ extracts an analytic prime divisor, and $w'(X\ni x)=a'$.
    \item If $a\geq 4$, then the weighted blow-up $f'':Y''\to X$ with the weight $w'':=(d,d,2,1)$ extracts an analytic prime divisor, and $w''(X\ni x)=2$. 
\end{enumerate}

\begin{align}\label{align: equation for cD case 1}
    v(g_0(x_3,x_4))\geq 2r+1,\ \ \ and \ \ \ v(g_1(x_3,x_4))\geq r+1.
\end{align}

\label{lem: cD irreducible case 2}
Let $f: Y\to X$ be a divisorial contraction of a prime divisor over $X\ni x$ and $r,a,d$ the corresponding positive integers as in Theorem~\ref{thm: kaw05 1.2 strenghthened}(2.2).
\begin{enumerate}
    \item For any weight $w':=(r'+1,r',a',1,r'+2)\in\mathbb Z_{>0}^5$ such that $r'+1=a'd$ and $2\leq a'<a$, the weighted blow-up $f':Y'\to X$ with the weight $w'$ extracts an analytic prime divisor, and $w'(X\ni x)=a'$. 
    \item If $a\geq 2$, then the weighted blow-up $f'':Y''\to X$ with the weight $w'':=(d,d,1,1,d)$ extracts an analytic prime divisor, and $w''(X\ni x)=1$. 
\end{enumerate}

\begin{align}\label{align: equation for cD case 2}
    v(g_0(x_3,x_4))\geq 2(r+1),\ \ v(g_1(x_3,x_4))\geq r+2,\ \ and\ \ v(g_2(x_3,x_4))\geq 2.
\end{align}

By Theorem~\ref{thm: kaw05 1.2 strenghthened}(3.1), analytically locally, we have  $$(X\ni x)\cong (\phi:= x_1^2+x_1x_3q(x_3^2,x_4)+x_2^2x_4+\lambda x_2x_3^{2\alpha-1}+p(x_3^2,x_4)=0)\subset (\mathbb C^4\ni o)/\frac{1}{2}(1,1,1,0),$$ and $f: Y\to X$ is a weighted blow-up with the weight $w:=\frac{1}{2}(r+2,r,a,2)$, such that 
\begin{itemize}
    \item $w(\phi)=w(x_2^2x_4)=r+1=ad$, where $a,r$ is odd,
    \item if $q(x^2_3,x_4)\not=0$, then $w(x_1x_3q(x_3^2,x_4))=r+1$, and
    \item $x_3^{2d}\in p(x_3^2,x_4)$.
\end{itemize}

Consider the weights $v=(v(x_3),v(x_4))=\frac{1}{2}(a,2)$ and $v'=(v'(x_3),v'(x_4))=\frac{1}{2}(a',2)$, we have $v'\succeq \frac{a'}{a}v$ (see Definition~\ref{defn: compare two weights}), and for any monomial term $x_3^{k}x_4^l$, $v'(x_3^{k}x_4^l)=\frac{a'}{a}v(x_3^{k}x_4^l)$ if and only if $l=0$.

If $q(x_3^2,x_4)\neq 0$, then $w(x_1x_3q(x_3^2,x_4))=\frac{1}{2}(r+2+a)+v(q(x_3^2,x_4))= r+1$, and $v(q(x_3^2,x_4))= \frac{r-a}{2}$. It follows that
\begin{align*}
    w'(x_1x_3q(x_3^2x_4))&=\frac{1}{2}(r'+2+a')+v'(q(x_3^2,x_4))\geq \frac{1}{2}(r'+2+a')+\frac{a'}{a}\frac{r-a}{2}\\
    &=\frac{1}{2}(r'+2+a')+\frac{a'}{a}\frac{a(d-1)-1}{2}=r'+1+\frac{1}{2}(1-\frac{a'}{a})> r'+1.
\end{align*}
Since $w(x_2x_3^{2\alpha-1})=\frac{1}{2}(r+(2\alpha-1)a)\geq r+1$, $2\alpha-1\geq \lceil\frac{r+2}{a}\rceil=\lceil\frac{ad+1}{a}\rceil=d+1$, hence
\begin{align*}
    w'(x_2x_3^{2\alpha-1})&=\frac{1}{2}(r'+a'(2\alpha-1))\geq \frac{1}{2}(r'+a'(d+1))=\frac{1}{2}(2r'+1+a')>r'+1,
\end{align*}
where the last inequality follows from $a'\geq 2$. Note that
\begin{align*}
    w'(p(x_3^2,x_4))&=v'(p(x_3^2,x_4))\geq\frac{a'}{a}(r+1)=r'+1=w'(x_3^{2d})\geq w'(p(x_3^2,x_4)),
\end{align*}
and $x_3^{2d}$ is the only monomial term in $p(x_3^2,x_4)$ whose weight equals $r'+1$. Note also that $w'(x_2^2x_4)=r'+1$ and $w'(x_1^2)=r'+2>r'+1$. Hence $w'(\phi)=r'+1$, and the $w'$-weighted leading term $$\phi_{w'}=x_2^2x_4+x_3^{2d}.$$ Since $(\phi_{w'}=0)$ defines an integral scheme near $o\in \mathbb{C}^4$, by Lemma~\ref{lem: weight leading term irr imply irr exceptional divisor}, the exceptional divisor of $f'$ is a prime divisor. Since $w'(X\ni x)=\frac{1}{2}(r'+2+r'+a'+2)-w'(\phi)-1$ and $w'(\phi)=r'+1$, $w'(X\ni x)=\frac{a'}{2}$.

\begin{align*}
    w'(x_2x_3^{2\alpha-1})&=\frac{1}{2}(r'+a'(2\alpha-1))\geq \frac{1}{2}(r'+a'(d+1))=\frac{1}{2}(2r'+1+a')>r'+1,
\end{align*}

\label{lem: transform pair to ideal adic}
Let ${\Gamma}\subset [0,+\infty)$ be a DCC (resp. finite) set. Then there exists a positive real number $\delta$ and a DCC (resp. finite) set ${\Gamma}'\subset [0,+\infty)$ depending only on ${\Gamma}$ satisfying the following. Assume that $(X\ni x,B,\mathfrak{a})$ is a $\mathbb{Q}$-factorial threefold triple such that $X$ is terminal, $B,\mathfrak{a}\in{\Gamma}$ and ${\rm{mld}}(X\ni x,B,\mathfrak{a})\geq 1-\delta$. Suppose that $\mathfrak{a}\not=\mathfrak{0}$. Then
\begin{enumerate}
    \item there exists an $\mathbb{R}$-ideal $\mathfrak{a}'\in{\Gamma}'$, such that $a(E,X,B,\mathfrak{a})=a(E,X,\mathfrak{a}')$ for any prime divisor $E$ over $X\ni x$, and
    \item there exists an $\mathbb{R}$-divisor $B'\in{\Gamma}'$, such that ${\rm{mld}}(X\ni x,B')={\rm{mld}}(X\ni x,B,\mathfrak{a})$.
\end{enumerate}

\label{thm: ideal adic semicontinuity termial threefolds}
Let ${\Gamma}$ be a DCC set of real numbers. Then there exists a positive real integer $l$ depending only on ${\Gamma}$ satisfying the following. Assume that $(X\ni x,B,\mathfrak{a})$ and $(X\ni x,B,\mathfrak{b})$ are two threefold triples, such that
\begin{itemize}
    \item $X$ is terminal,
    \item ${\rm{mld}}(X\ni x,B,\mathfrak{a})\geq 1$ and ${\rm{mld}}(X\ni x,B,\mathfrak{b})\geq 1$,
\item $\mathfrak{a}=\prod^m_i\mathfrak{a}_i^{\gamma_i}$ and $\mathfrak{b}=\prod^m_i\mathfrak{b}_i^{\gamma_i}$, where $m>0$, $\mathfrak{a}_i$ and $\mathfrak{b}_i$ are ideals, $\gamma_i\in{\Gamma}$, and
    \item $\mathfrak{a}_i+\mathfrak{m}^l=\mathfrak{b}_i+\mathfrak{m}^l$ for each $i$, where $\mathfrak{m}$ is the maximal ideal of $\mathcal{O}_{X,x}$.
\end{itemize}
Then ${\rm{mld}}(X\ni x,B,\mathfrak{a})={\rm{mld}}(X\ni x,B,\mathfrak{b})$.

\label{thm: gl conjecture terminal threefolds}
Let $\gamma_1,\dots,\gamma_m\in [0,1]$ be real numbers. Let $x\in X$ be a terminal threefold singularity and $\{\mathfrak{a}_i=\prod_{i=1}^m\mathfrak{a}_{i,j}^{\gamma_j}\}_{i=1}^{\infty}$ a sequence of $\mathbb{R}$-ideals on $X$, such that ${\rm{mld}}(X\ni x,\mathfrak{a}_i)\geq 1$ for each $i$ and each $\mathfrak{a}_{i,j}$ is an ideal. Let $(\widehat X\ni \widehat x,\widehat{\mathfrak{a}})$ be the generic limit of $\{(X\ni x,\mathfrak{a}_i)\}_{i=1}^{\infty}$ and let $\widehat{\mathfrak{a}}_{j}$ be the generic limit of $\{\widehat{\mathfrak{a}}_{i,j}\}_{i=1}^{\infty}$ for each $j$. Then there exists an infinite subset $\Lambda\subset\mathbb{Z}_{>0}$, such that
\begin{enumerate}
    \item $\widehat{\mathfrak{a}}_j$ is the generic limit of $\{\mathfrak{a}_{i,j}\}_{i\in\Lambda}$ for each $j$, and
    \item ${\rm{mld}}(\widehat X\ni\widehat x,\widehat{\mathfrak{a}})={\rm{mld}}(X\ni x,\mathfrak{a}_i)$ for every $i\in\Lambda$.
\end{enumerate}

By Theorem \ref{thm: ideal adic semicontinuity termial threefolds} and \cite[Proposition 2.2 iv)]{MN18}, there exists a positive integer $l$, such that for any integer $s\geq l$ and any $i$, we have
\begin{equation}\label{equ: first equation gl conj}
{\rm{mld}}(X\ni x,\prod_{i=1}^m(\mathfrak{a}_{i,j}+\mathfrak{m}_x^s)^{\gamma_j})={\rm{mld}}(X\ni x,\prod_{i=1}^m\mathfrak{a}_{i,j}^{\gamma_j})={\rm{mld}}(X\ni x,\mathfrak{a}_i),  
\end{equation}
where $\mathfrak{m}_x$ is the maximal ideal of $\mathcal{O}_{X,x}$. 

Let $E$ be a prime divisor over $\widehat X\ni\widehat x$ which computes ${\rm{mld}}(\widehat X\ni\widehat x,\widehat{\mathfrak{a}})$. Let $s_0\geq l$ be an integer, such that $s_0\operatorname{mult}_E\mathfrak{m}_{\widehat x}\geq\operatorname{mult}_E\widehat a_j$ for each $j$, where $\mathfrak{m}_{\widehat x}$ is the maximal ideal of $\mathcal{O}_{\widehat X,\widehat x}$. By \cite[Proposition 2.2 iv)]{MN18}, we have 
\begin{equation}\label{equ: second equation gl conj}
{\rm{mld}}(\widehat X\ni\widehat x,\widehat{\mathfrak{a}})={\rm{mld}}(\widehat X\ni\widehat x,\prod_{i=1}^m\widehat{\mathfrak{a}}_j^{\gamma_j})={\rm{mld}}(\widehat X\ni\widehat x,\prod_{i=1}^m(\widehat{\mathfrak{a}}_j+\mathfrak{m}_{\widehat x}^{s_0})^{\gamma_j}).
\end{equation}
By \cite[Remark 3.2]{MN18}, there exists an infinite subset $\Lambda\subset\mathbb{Z}_{>0}$, such that
\begin{equation}\label{equ: third equation gl conjecture}
{\rm{mld}}(\widehat X\ni\widehat x,\prod_{i=1}^m(\widehat{\mathfrak{a}}_j+\mathfrak{m}_{\widehat x}^{s_0})^{\gamma_j})={\rm{mld}}(X\ni x,\prod_{i=1}^m(\mathfrak{a}_{i,j}+\mathfrak{m}_x^{s_0})^{\gamma_j})
\end{equation}
for any $i\in\Lambda$. We get the desired result by combining \eqref{equ: first equation gl conj}, \eqref{equ: second equation gl conj}, and \eqref{equ: third equation gl conjecture}.

